-- SALY / S+AM: 14 fuentes VALIDADAS -> 14 NUEVA CANDIDATA por saly.nucleo_regla_proponer_v1.
-- NO publicar; juicio contexto actual/no independiente y DEVOLVER. Sin modificar saly.reglas.
-- Sin crear nodo EMPLEADO ni configurar SALY_PLUS/ANTICIPATION_DAYS (NULL en fuente).
-- EKB comprobado antes: no duplicar hallazgos; brechas explicitadas en artifact JSON.
BEGIN;
DO $pre$
DECLARE old_src jsonb; want_src jsonb;
BEGIN
 IF (SELECT count(*) FROM saly.reglas)<>14
 OR (SELECT count(*) FROM saly.nucleo_reglas)<>0
 OR (SELECT count(*) FROM saly.nucleo_hechos)<>0
 OR (SELECT count(*) FROM saly.nucleo_parametros)<>0
 OR (SELECT count(*) FROM saly.nucleo_juicios)<>0
 OR (SELECT count(*) FROM saly.nucleo_rubrica WHERE estado='ACTIVO')<>7
 OR (SELECT count(*) FROM saly.nucleo_nodos WHERE codigo IN('GLOBAL','ADELANTO'))<>2
 OR (SELECT count(*) FROM saly.nucleo_familias WHERE codigo IN('MOTOR_DISPONIBLE','CALENDARIO','GOBERNANZA') AND estado='ACTIVA')<>3
 OR EXISTS(SELECT 1 FROM saly.config_global WHERE
       (scope='MOTOR_DISPONIBLE' AND config_key IN('CURVE_TYPES','ASSIGNMENT_CAP_PCT_DEFAULT'))
        OR (scope='CALENDARIO' AND config_key IN('ON_MISSING_DAY','CONFIG_CHANGE_DEFAULT')))
 THEN RAISE EXCEPTION 'SALY_AM14_PRESTATE_DRIFT'; END IF;
