DO $apply$
DECLARE item jsonb; p jsonb; judge jsonb; result jsonb; verdict jsonb; dry jsonb; negative jsonb;
 hash_actual text; original_count integer; original_hash text; old_lf_count integer; old_lf_hash text;
 observed_src jsonb; expected_src jsonb; code text; n integer:=0;
BEGIN
 SELECT count(*),md5(COALESCE(string_agg(to_jsonb(x)::text,'|' ORDER BY id),'')) INTO original_count,original_hash FROM saly.reglas x;
 SELECT count(*),md5(COALESCE(string_agg(to_jsonb(x)::text,'|' ORDER BY id),'')) INTO old_lf_count,old_lf_hash FROM lf_ops.reglas x;
 FOR item IN SELECT value FROM jsonb_array_elements($salyjson$[{"source":{"id":1,"codigo":"SALY-RGL-001","categoria":"MOTOR_DISPONIBLE","titulo":"Curvas core del motor","regla":"El motor admite LINEAR, STEPS e INSTANT. INSTANT equivale a STEPS con liberación 100%.","razon":"Evita motores específicos por empresa o periodicidad.","alcance":"PRODUCTO","producto_codigo":"ADELANTO","valor_config":{"curve_types":["LINEAR","STEPS","INSTANT"]},"estado":"VALIDADO","vigente":true,"decision_id":51,"fuente":"Motor Disponible V2.3","metadata":{"version":"V2.3"},"es_transversal":false},"paquete":{"tipo":"NUEVA","codigo":"SALY-RGL-001","clave":"saly_motor_1","familia":"MOTOR_DISPONIBLE","naturaleza":"DEFINICION","titulo":"Curvas core del motor","descripcion":"Curvas LINEAR/STEPS/INSTANT admitidas por el motor; la equivalencia INSTANT con liberación completa requiere verificar cálculo real.","dueno":"PRODUCTO","autoridad":"SALY-DEC-51","alcance":"ADELANTO","modo":"HEREDA","clase":"BACKEND","efecto":"CLASIFICAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"saly.reglas/1","solicitante":"migracion-nucleo-saly"},"condicion":{"op":"o","izq":{"op":"=","izq":{"hecho":"curva_tipo"},"der":{"lit":"LINEAR"}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"curva_tipo"},"der":{"lit":"STEPS"}},"der":{"op":"=","izq":{"hecho":"curva_tipo"},"der":{"lit":"INSTANT"}}}},"pruebas":[{"casuistica":"VALOR_TIPICO","entrada":{"curva_tipo":"INSTANT"},"esperado":true},{"casuistica":"VALOR_BORDE","entrada":{"curva_tipo":"INVALID"},"esperado":false}]},"juicio":{"veredicto":"DEVOLVER","juez":"GPT-6 juicio contexto actual; no independiente","modo":"CONTEXTO_ACTUAL","revisor_es_productor":true,"llamadas_modelo":0,"puntajes":{"CAL_ACCIONABLE":{"puntaje":1,"observacion":"La condición representa una verificación observable propuesta, no ejecución existente."},"CAL_ALCANCE":{"puntaje":1,"observacion":"Producto y globales declarados según la fuente vigente."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Define el caso y reserva las dependencias sin binding como brechas verificables."},"COH_EFECTO":{"puntaje":1,"observacion":"Efecto coherente con bloqueo, permiso o clasificación de la condición acotada."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"Sólo un guard lógico de cláusulas de la fuente; requiere pruebas de runtime o fórmula."},"SEM_NO_CONTRADICE":{"puntaje":0.5,"observacion":"Comparación de fuentes SALY sin evidencia de motor implementado; no se certifican interacciones."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"No existen candidatas SALY previas; equivalencia semántica completa entre reglas no juzgada independientemente."}}}},{"source":{"id":2,"codigo":"SALY-RGL-002","categoria":"MOTOR_DISPONIBLE","titulo":"Assignment cap","regla":"assignment_cap limita la base antes del devengo y puede expresarse como porcentaje y/o monto.","razon":"Distingue la elegibilidad inicial del límite de acumulación o retiro.","alcance":"PRODUCTO","producto_codigo":"ADELANTO","valor_config":{"pct_default":1,"amount_default":null},"estado":"VALIDADO","vigente":true,"decision_id":53,"fuente":"Motor Disponible V2.3","metadata":{"version":"V2.3"},"es_transversal":false},"paquete":{"tipo":"NUEVA","codigo":"SALY-RGL-002","clave":"saly_motor_2","familia":"MOTOR_DISPONIBLE","naturaleza":"CONDUCTA","titulo":"Assignment cap","descripcion":"Bloquear cálculo si assignment_cap no limita la base antes del devengo; porcentaje/monto son configuración de fuente, sin valores incrustados.","dueno":"PRODUCTO","autoridad":"SALY-DEC-53","alcance":"ADELANTO","modo":"HEREDA","clase":"BACKEND","efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"saly.reglas/2","solicitante":"migracion-nucleo-saly"},"condicion":{"op":"=","izq":{"hecho":"cap_antes_devengo"},"der":{"lit":false}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"cap_antes_devengo":false},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"cap_antes_devengo":true},"esperado":false}]},"juicio":{"veredicto":