erificación observable propuesta, no ejecución existente."},"CAL_ALCANCE":{"puntaje":1,"observacion":"Producto y globales declarados según la fuente vigente."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Define el caso y reserva las dependencias sin binding como brechas verificables."},"COH_EFECTO":{"puntaje":1,"observacion":"Efecto coherente con bloqueo, permiso o clasificación de la condición acotada."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"Sólo un guard lógico de cláusulas de la fuente; requiere pruebas de runtime o fórmula."},"SEM_NO_CONTRADICE":{"puntaje":0.5,"observacion":"Comparación de fuentes SALY sin evidencia de motor implementado; no se certifican interacciones."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"No existen candidatas SALY previas; equivalencia semántica completa entre reglas no juzgada independientemente."}}}}]$salyjson$::jsonb) LOOP
   p:=item->'paquete'; judge:=item->'juicio'; code:=p->>'codigo';
   -- Control negativo: hecho inexistente o cambio de fuente rechaza la puerta.
   negative:=saly.nucleo_regla_proponer_v1(p||jsonb_build_object('condicion',jsonb_build_object('op','=','izq',jsonb_build_object('hecho','NO_EXISTE_SALY'),'der',jsonb_build_object('lit',true))),false);
   IF negative->>'resultado'<>'RECHAZADA' OR (negative->>'bloqueantes')::int=0
   THEN RAISE EXCEPTION 'SALY_AM14_UNKNOWN_FACT_BYPASS % %',code,negative; END IF;
   dry:=saly.nucleo_regla_proponer_v1(p,false);
   IF dry->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (dry->>'bloqueantes')::int<>0
   THEN RAISE EXCEPTION 'SALY_AM14_GATE_REJECT % %',code,dry; END IF;
   result:=saly.nucleo_regla_proponer_v1(p,true);
   IF result->>'resultado'<>'CANDIDATA' OR (result->>'version')::int<>1
   THEN RAISE EXCEPTION 'SALY_AM14_NOT_CANDIDATE % %',code,result; END IF;
   IF (SELECT ficha FROM saly.nucleo_regla_versiones WHERE regla=code AND version=1) IS DISTINCT FROM p-'pruebas'
     OR (SELECT origen FROM saly.nucleo_regla_versiones WHERE regla=code AND version=1) IS DISTINCT FROM p->'origen'
     OR (SELECT jsonb_agg(jsonb_build_object('casuistica',casuistica,'entrada',entrada,'esperado',esperado) ORDER BY pr.n)
         FROM saly.nucleo_regla_pruebas pr WHERE pr.regla=code AND version=1) IS DISTINCT FROM p->'pruebas'
     OR (SELECT regla_legacy_id FROM saly.nucleo_reglas WHERE codigo=code) IS NOT NULL
   THEN RAISE EXCEPTION 'SALY_AM14_PACKAGE_MISMATCH_OR_LEGACY_FK %',code; END IF;
   hash_actual:=saly.nucleo_hash_paquete_v1(code,1);
   BEGIN
     PERFORM saly.nucleo_juicio_registrar_v1(judge||jsonb_build_object('regla',code,'hash_evaluado',repeat('0',64),
       'evidencia_ref','https://github.com/cristhianlujan/claude-persona-lf-patch/blob/main/sandbox/lf_contract_gate_test/nucleo_ci/saly_am_14_v1.json#'||code));
     RAISE EXCEPTION 'SALY_AM14_BAD_HASH_ACCEPTED %',code;
   EXCEPTION WHEN others THEN
     IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF;
   END;
   PERFORM saly.nucleo_juicio_registrar_v1(judge||jsonb_build_object('regla',code,'hash_evaluado',hash_actual,
       'evidencia_ref','https://github.com/cristhianlujan/claude-persona-lf-patch/blob/main/sandbox/lf_contract_gate_test/nucleo_ci/saly_am_14_v1.json#'||code));
   verdict:=saly.nucleo_regla_evaluar_v1(code,true);
   IF verdict->>'decision'<>'DEVUELTA' OR (SELECT estado FROM saly.nucleo_regla_versiones WHERE regla=code AND version=1)<>'CANDIDATA'
   THEN RAISE EXCEPTION 'SALY_AM14_UNSAFE_VERDICT % %',code,verdict; END IF;
   -- Negativo idempotencia: no duplicar identidad tras el alta.
   negative:=saly.nucleo_regla_proponer_v1(p,false);
   IF negative->>'resultado'<>'RECHAZADA' THEN RAISE EXCEPTION 'SALY_AM14_DUPLICATE_NOT_REJECTED % %',code,negative; END IF;
   RAISE NOTICE 'SALY_AM14_RESULT %',jsonb_build_object('codigo',code,'version',1,'nota',verdict->'nota','decision',verdict->>'decision',
      'hash_paquete',hash_actual,'origen',p->'origen','juicio_modo',judge->>'modo');
   n:=n+1;
 END LOOP;
