opuesta, no ejecución existente."},"CAL_ALCANCE":{"puntaje":1,"observacion":"Producto y globales declarados según la fuente vigente."},"CAL_CLARIDAD":{"puntaje":1,"observacion":"Define el caso y reserva las dependencias sin binding como brechas verificables."},"COH_EFECTO":{"puntaje":1,"observacion":"Efecto coherente con bloqueo, permiso o clasificación de la condición acotada."},"COH_TEXTO_CONDICION":{"puntaje":0.5,"observacion":"Sólo un guard lógico de cláusulas de la fuente; requiere pruebas de runtime o fórmula."},"SEM_NO_CONTRADICE":{"puntaje":0.5,"observacion":"Comparación de fuentes SALY sin evidencia de motor implementado; no se certifican interacciones."},"SEM_NO_DUPLICA":{"puntaje":0.5,"observacion":"No existen candidatas SALY previas; equivalencia semántica completa entre reglas no juzgada independientemente."}}}}]$salyjson$::jsonb) AS x(value);
 IF observed_src IS DISTINCT FROM expected_src
 OR (SELECT count(*) FROM saly.reglas)<>original_count
 OR (SELECT md5(COALESCE(string_agg(to_jsonb(x)::text,'|' ORDER BY id),'')) FROM saly.reglas x) IS DISTINCT FROM original_hash
 OR (SELECT count(*) FROM lf_ops.reglas)<>old_lf_count
 OR (SELECT md5(COALESCE(string_agg(to_jsonb(x)::text,'|' ORDER BY id),'')) FROM lf_ops.reglas x) IS DISTINCT FROM old_lf_hash
 OR n<>14
 OR (SELECT count(*) FROM saly.nucleo_reglas WHERE estado='CANDIDATA')<>14
 OR (SELECT count(*) FROM saly.nucleo_regla_versiones WHERE estado='CANDIDATA')<>14
 OR (SELECT count(*) FROM saly.nucleo_juicios WHERE modo='CONTEXTO_ACTUAL' AND revisor_es_productor=true AND llamadas_modelo=0)<>14
 OR (SELECT count(*) FROM saly.nucleo_evaluaciones WHERE decision='DEVUELTA')<>14
 OR (SELECT count(*) FROM saly.nucleo_regla_versiones WHERE estado='PUBLICADA')<>0
 OR (SELECT count(*) FROM saly.nucleo_hechos)<>31
 OR (SELECT count(*) FROM saly.nucleo_parametros)<>4
 OR (SELECT count(*) FROM saly.nucleo_familia_vocabulario)<>31
 OR (SELECT count(*) FROM saly.config_global WHERE
       (scope='MOTOR_DISPONIBLE' AND config_key IN('CURVE_TYPES','ASSIGNMENT_CAP_PCT_DEFAULT'))
        OR (scope='CALENDARIO' AND config_key IN('ON_MISSING_DAY','CONFIG_CHANGE_DEFAULT')))<>4
 OR EXISTS(SELECT 1 FROM saly.nucleo_reglas WHERE regla_legacy_id IS NOT NULL)
 THEN RAISE EXCEPTION 'SALY_AM14_READBACK_FAILED'; END IF;
 RAISE NOTICE 'SALY_AM14_PASS 14/14 CANDIDATA, 14 juicios CONTEXTO_ACTUAL DEVOLVER, 14 evaluaciones DEVUELTA, 0 PUBLICADA, 14 legadas intactas, 31 hechos, 4 config/parametros, LF intacto';
END $apply$;
